/* Vietnamese workspaces. Commands and calculations live in PemaCRM. */
(() => {
  const P=window.Pema,C=window.PemaCRM,O=window.PemaOps,e=P.esc,I=PemaUI.icon;
  let host,rule='all',owner=window.PemaStaff?.current().owner||'all',query='',queuePage=1,queueMode='due',todayStatus='all',todayQuery='',todayDoctor='all',todayPage=1;
  const statuses={booked:'Chưa đến',confirmed:'Đã xác nhận',arrived:'Đang chờ',in_progress:'Đang khám/điều trị',completed:'Hoàn tất',cancelled:'Đã hủy',missed:'Vắng hẹn'};
  const labelPriority={high:'Ưu tiên cao',normal:'Thông thường',low:'Chăm sóc'};
  const btn=(text,action,id='',primary=false)=>`<button class="btn ${primary?'btn-primary':''}" data-crm="${action}" data-id="${e(id)}">${text}</button>`;
  const field=(label,id,html)=>`<div class="field"><label for="${id}">${label}</label>${html}</div>`;
  const select=(id,items,value)=>`<select id="${id}">${items.map(([v,l])=>`<option value="${e(v)}" ${v===value?'selected':''}>${e(l)}</option>`).join('')}</select>`;
  const owners=['CSKH Mai Anh','CSKH Thu','BS. Tâm','BS. Mai','BS. An','BS. Lan'];
  const head=(title,description,actions='')=>`<div class="page-heading"><div><div class="eyebrow">Pema · chăm sóc xuyên suốt</div><h1 class="page-title">${title}</h1><p class="subtitle">${description}</p></div><div class="actions">${actions}</div></div>`;
  const badge=(text,warn=false)=>`<span class="status ${warn?'status-yellow':'status-blue'}">${e(text)}</span>`;
  const day=iso=>iso?P.date(iso):'Chưa thiết lập';
  function tile(label,value,detail,action='queue',id='all'){return `<button class="crm-kpi" data-crm="${action}" data-id="${id}"><span>${label}${I('chevron-right')}</span><strong>${value}</strong><small>${detail}</small></button>`;}
  function summary(p) {const c=C.profile(p);return `<section class="crm-summary"><div><span class="eyebrow">${e(c.demoCase||'Bước tiếp theo')}</span><h3>${c.overdueDays?'Quá hạn '+c.overdueDays+' ngày':c.expectedNextVisitAt?'Dự kiến quay lại '+day(c.expectedNextVisitAt):'Chưa có ngày dự kiến'}</h3><p>${e(c.expectedVisitReason||'Cần bác sĩ thiết lập mốc tiếp theo')} · ${e(C.sources[c.expectedVisitSource]||'Chưa có nguồn')}</p></div><div>${badge(C.stageLabels[c.lifecycleStage],c.riskLevel==='high')}<small>Phụ trách: ${e(c.owner)} · ${c.marketingOptOut?'Đã từ chối marketing':'Có thể chăm sóc theo kế hoạch'}</small></div><div class="actions">${btn('CRM & CSKH','patient-crm',p.id)}${btn('Sửa ngày dự kiến','expected',p.id)}</div></section>`;}
  function queue() {
    if(window.PemaStaff?.current().role==='doctor')return doctorHome();
    const m=C.metrics(),all=C.queue({allDates:queueMode==='all',owner}),rows=all.filter(t=>(rule==='all'||t.type===rule||rule==='at_risk'&&C.profile(P.patient(t.patientId)).riskLevel==='high')&&(owner==='all'||t.owner===owner)&&(!query||[P.patient(t.patientId).name,t.patientId,t.reason].join(' ').toLowerCase().includes(query.toLowerCase())));
    queuePage=Math.min(queuePage,Math.max(1,Math.ceil(rows.length/12)));const list=rows.slice((queuePage-1)*12,queuePage*12);
    return head('CSKH hôm nay','Từ dữ liệu khám đến việc cần làm · ngày demo 20/09/2026',btn('Xem protocol','protocol'))+`<div class="crm-kpis">${tile('Việc CSKH toàn đội',m.pending,m.patients+' khách cần chăm sóc')}${tile('Quá hạn',m.overdueTasks,'Ưu tiên gọi và xác nhận')}${tile('Đã hoàn tất',m.completed,'Có kết quả được ghi nhận','activity')}${tile('Đặt lịch sau CSKH',m.booked,'Chưa đồng nghĩa đã quay lại','activity')}</div><div class="crm-workspace"><aside class="panel crm-groups"><h2>Nhóm công việc</h2>${btn('Tất cả · '+all.length,'filter','all',rule==='all')}${P.state.crmAutomationRules.map(r=>btn(e(r.name)+' <span>'+all.filter(t=>t.type===r.id).length+'</span>','filter',r.id,rule===r.id)).join('')}<div class="notice">Theo dõi lâm sàng và CSKH là hai hàng đợi riêng. Phản hồi cần bác sĩ sẽ được chuyển sang Theo dõi.</div></aside><section class="panel crm-queue"><div class="panel-head"><div class="panel-title">${rule==='all'?'Danh sách cần chăm sóc':e(rule==='at_risk'?'Khách có nguy cơ mất':P.state.crmAutomationRules.find(r=>r.id===rule)?.name||rule)}<small>${rows.length} việc · không gửi tin tự động</small></div></div><div class="crm-toolbar">${field('Tìm khách / lý do','crm-search',`<input id="crm-search" placeholder="Tên hoặc mã hồ sơ…" value="${e(query)}">`)}${field('Phụ trách','crm-owner-filter',select('crm-owner-filter',[['all','Tất cả nhân viên'],...owners.map(x=>[x,x])],owner))}${field('Thời hạn','crm-mode',select('crm-mode',[['due','Đến hạn + sinh nhật tuần'],['all','Tất cả, gồm đã hẹn lại']],queueMode))}</div><div class="crm-table-scroll"><table class="table crm-table"><thead><tr><th>Khách hàng / bối cảnh</th><th>Lý do & bước đề xuất</th><th>Hạn xử lý</th><th>Phụ trách</th><th></th></tr></thead><tbody>${list.map(t=>{const p=P.patient(t.patientId),c=C.profile(p);return `<tr><td><button class="crm-name" data-crm="profile" data-id="${p.id}">${e(p.name)}</button><small>${p.id} · Còn ${c.remaining} buổi · ${P.money(p.invoices.reduce((sum,i)=>sum+(i.paid?i.amount:i.received||0),0))} đã thu</small>${c.demoCase?`<span class="crm-case">${e(c.demoCase)}</span>`:''}</td><td><strong>${e(t.reason)}</strong><small>${e(t.suggestedAction)}</small>${badge(labelPriority[t.priority],t.priority==='high')}</td><td>${day(t.dueAt)}<small>${t.dueAt.slice(0,10)<C.DAY?'Trễ '+PemaCRMData.days(t.dueAt)+' ngày':t.status==='rescheduled'?'Đã hẹn lại':'Theo kế hoạch'}</small></td><td>${e(t.owner)}<small>Liên hệ gần nhất: ${day(c.lastContactAt)}</small></td><td>${btn('Xử lý →','task',t.id,true)}</td></tr>`;}).join('')||'<tr><td colspan="5"><div class="empty">Không có việc phù hợp. Thử nhóm khác hoặc xem các việc đã hẹn lại.</div></td></tr>'}</tbody></table></div><div class="invoice-pagination"><span>${rows.length} việc · Trang ${queuePage}/${Math.max(1,Math.ceil(rows.length/12))}</span><div class="actions">${btn('← Trước','queue-page','-1')}${btn('Sau →','queue-page','1')}</div></div></section></div>`;
  }
  function dashboard() {
    const m=C.metrics(),o=O.seed(),a=o.appointments.filter(a=>a.date===C.DAY),revenue=P.state.patients.flatMap(p=>p.invoices).filter(i=>i.date===C.DAY).reduce((s,i)=>s+i.amount,0);
    return head('Chào buổi sáng, BS. Tâm','Vận hành hôm nay và chăm sóc khách hàng · mốc demo 20/09/2026',`<button class="btn" data-nav="today">Lịch hôm nay →</button>${btn('Mở CSKH hôm nay','queue','all',true)}`)+`<div class="metrics crm-operating"><div class="metric-card"><div class="metric-label">Lịch hôm nay</div><div class="metric-value">${a.length}</div><button class="btn btn-quiet" data-nav="today">Mở tiếp đón →</button></div><div class="metric-card"><div class="metric-label">Đã đến / đang chờ</div><div class="metric-value">${a.filter(x=>['arrived','in_progress','completed'].includes(x.status)).length} <small>/ ${a.filter(x=>x.status==='arrived').length}</small></div><button class="btn btn-quiet" data-nav="today">Bàn giao phòng khám →</button></div><div class="metric-card"><div class="metric-label">Vắng hẹn</div><div class="metric-value">${a.filter(x=>x.status==='missed').length}</div>${btn('Xử lý vắng hẹn','queue','no_show')}</div><div class="metric-card"><div class="metric-label">Phát sinh hôm nay</div><div class="metric-value crm-money">${P.money(revenue)}</div><button class="btn btn-quiet" data-nav="cashier">Hóa đơn, không phải thực thu →</button></div></div><div class="crm-kpis">${tile('Khách cần CSKH',m.patients,m.pending+' việc đến hạn')}${tile('Quá ngày dự kiến',m.overduePatients,'Cần hỗ trợ chọn lịch','queue','overdue')}${tile('Nguy cơ mất khách',m.atRisk,'Quá hạn hoặc bỏ dở','queue','at_risk')}${tile('Liệu trình bỏ dở',m.abandoned,'Còn buổi, >45 ngày','queue','abandoned')}</div><div class="crm-dashboard-grid"><section class="panel"><div class="panel-head"><div class="panel-title">Ưu tiên chăm sóc<small>Từ dữ liệu khám và lịch hẹn, có người phụ trách</small></div>${btn('Tất cả →','queue')}</div><div class="crm-table-scroll"><table class="table crm-table"><thead><tr><th>Khách hàng</th><th>Việc tiếp theo</th><th>Phụ trách</th><th></th></tr></thead><tbody>${C.queue().filter((t,i,a)=>a.findIndex(x=>x.patientId===t.patientId)===i).slice(0,5).map(t=>`<tr><td><button class="crm-name" data-crm="profile" data-id="${t.patientId}">${e(P.patient(t.patientId).name)}</button><small>${t.patientId}</small></td><td>${e(t.reason)}<small>${day(t.dueAt)}</small></td><td>${e(t.owner)}</td><td>${btn('Xử lý','task',t.id)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-title">Hiệu quả CSKH<small>Kết quả thực từ hoạt động đã lưu</small></div><dl class="crm-facts"><div><dt>Việc đã hoàn tất</dt><dd>${m.completed}</dd></div><div><dt>Liên hệ thành công</dt><dd>${m.contactRate}% <small>${m.contacted}/${m.attempted} lần liên hệ</small></dd></div><div><dt>Lịch đặt sau CSKH</dt><dd>${m.booked}</dd></div><div><dt>Đã quay lại thực tế</dt><dd>${m.reactivated}</dd></div><div><dt>Việc quá hạn</dt><dd>${m.overdueTasks}</dd></div></dl>${btn('Xem nhật ký kết quả','activity')}<div class="notice">Khách đặt lịch chưa được tính là đã quay lại. Chỉ ghi nhận quay lại khi check-in sau CSKH.</div></section></div><section class="panel crm-lifecycle"><div class="panel-title">Vòng đời khách hàng<small>Một hồ sơ, nhiều lần chăm sóc</small></div><div class="crm-stages">${Object.entries(m.stages).map(([k,v])=>`<button data-crm="segment" data-id="${k}"><strong>${v}</strong><span>${C.stageLabels[k]}</span></button>`).join('')}</div></section>`;
  }
  function doctorHome() {
    const a=PemaStaff.current(),patients=P.state.patients.filter(PemaStaff.owns),visits=O.seed().appointments.filter(x=>x.doctor===a.doctor&&x.date===C.DAY),followups=P.state.followups.filter(f=>f.status==='open'&&patients.some(p=>p.id===f.patient));
    return head('Không gian bác sĩ · '+a.name,'Lịch cá nhân, hồ sơ phụ trách và phản hồi cần xem.',`<a class="btn" href="${PemaStaff.financeUrl()}">Doanh số của tôi →</a><button class="btn btn-primary" data-nav="today">Lịch khám của tôi →</button>`)+`<div class="crm-kpis">${tile('Lịch hôm nay',visits.length,'Lịch theo tài khoản bác sĩ','doctor-today')}${tile('Hồ sơ phụ trách',patients.length,'Patient 360 của bác sĩ','doctor-patients')}${tile('Cần bác sĩ xem',followups.length,'Phản hồi đang mở','doctor-followups')}</div><section class="panel"><div class="panel-title">Lịch khám của tôi<small>Không bao gồm dashboard CSKH hoặc tài chính toàn phòng khám</small></div><div class="crm-table-scroll"><table class="table crm-table"><thead><tr><th>Giờ</th><th>Bệnh nhân</th><th>Trạng thái</th><th></th></tr></thead><tbody>${visits.map(v=>`<tr><td>${v.time}</td><td>${e(P.patient(v.patient).name)}</td><td>${badge(statuses[v.status])}</td><td>${btn('Mở hồ sơ','profile',v.patient)}</td></tr>`).join('')}</tbody></table></div></section>`;
  }
  function today() {
    const o=O.seed(),all=o.appointments.filter(a=>a.date===C.DAY&&(!window.PemaStaff||PemaStaff.current().role!=='doctor'||a.doctor===PemaStaff.current().doctor)),rows=all.filter(a=>(todayStatus==='all'||a.status===todayStatus)&&(todayDoctor==='all'||a.doctor===todayDoctor)&&(!todayQuery||[a.patient,P.patient(a.patient).name,P.patient(a.patient).phone].join(' ').toLowerCase().includes(todayQuery.toLowerCase()))).sort((a,b)=>a.time.localeCompare(b.time));
    todayPage=Math.min(todayPage,Math.max(1,Math.ceil(rows.length/25)));const shown=rows.slice((todayPage-1)*25,todayPage*25);
    const total=P.state.patients.flatMap(p=>p.invoices).filter(i=>i.date===C.DAY).reduce((s,i)=>s+i.amount,0);
    return head('Hôm nay tại Pema','Tiếp đón theo từng lịch hẹn · dữ liệu tổng hợp 20/09/2026',`<button class="btn btn-primary" data-ops="new">＋ Đặt lịch mới</button>`)+`<div class="crm-reception-stats"><div><strong>${all.length}</strong><span>Tổng lịch</span></div><div><strong>${all.filter(a=>['arrived','in_progress','completed'].includes(a.status)).length}</strong><span>Đã đến</span></div>${['booked','arrived','in_progress','completed','cancelled','missed'].map(k=>`<button data-crm="today-status" data-id="${k}"><strong>${all.filter(a=>a.status===k||(k==='booked'&&a.status==='confirmed')).length}</strong><span>${statuses[k]}</span></button>`).join('')}${window.PemaStaff?.current().role==='doctor'?'':`<div><strong class="crm-money">${P.money(total)}</strong><span>Phát sinh hóa đơn hôm nay</span></div>`}</div><section class="panel"><div class="crm-toolbar">${field('Tên / mã KH / liên hệ','crm-today-search',`<input id="crm-today-search" value="${e(todayQuery)}" placeholder="Tìm nhanh khách…">`)}${field('Trạng thái','crm-today-status',select('crm-today-status',[['all','Tất cả trạng thái'],...Object.entries(statuses)],todayStatus))}${field('Bác sĩ','crm-today-doctor',select('crm-today-doctor',[['all','Tất cả bác sĩ'],...o.doctors.map(d=>[d.id,d.name])],todayDoctor))}</div><div class="crm-table-scroll crm-reception-table"><table class="table crm-table"><thead><tr><th>Giờ</th><th>Mã KH · bệnh nhân</th><th>Liên hệ</th><th>Nội dung</th><th>Trạng thái</th><th>Bác sĩ</th><th>Người tạo</th><th>Giá lịch dự kiến</th><th>Tiếp đón</th></tr></thead><tbody>${shown.map(a=>{const p=P.patient(a.patient);return `<tr><td><b>${a.time}</b></td><td><button class="crm-name" data-crm="profile" data-id="${p.id}">${e(p.name)}</button><small>${p.id}</small></td><td>${e(p.phone)}<small>${p.age} tuổi</small></td><td>${e(o.services.find(s=>s.id===a.service)?.name)}<small>${e(p.concern)}</small></td><td>${badge(statuses[a.status],['arrived','missed'].includes(a.status))}</td><td>${e(o.doctors.find(d=>d.id===a.doctor)?.name)}</td><td>${e(a.createdBy||'Lễ tân')}</td><td>${P.money(a.price)}</td><td><div class="actions">${['booked','confirmed'].includes(a.status)?btn('Check-in','arrive',a.id,true)+btn('Vắng','missed',a.id):a.status==='arrived'?btn('Mời vào phòng','start',a.id,true):btn('Mở 360','profile',p.id)}</div></td></tr>`;}).join('')||'<tr><td colspan="9">Không có lịch phù hợp.</td></tr>'}</tbody></table></div><div class="invoice-pagination"><span>${rows.length} lịch · Trang ${todayPage}/${Math.max(1,Math.ceil(rows.length/25))} · 25 dòng/trang</span><div class="actions">${btn('← Trước','today-page','-1')}${btn('Sau →','today-page','1')}</div></div></section>`;
  }
  function timeline(p,crmOnly=false) {const rows=C.timeline(p).filter(x=>!crmOnly||x.source.startsWith('CRM:'));return `<section class="panel"><div class="panel-title">${crmOnly?'Lịch sử CSKH':'Lịch sử hợp nhất'}<small>Sự kiện gốc, người ghi nhận và liên kết công việc</small></div><div class="timeline crm-timeline">${rows.map(x=>`<article class="timeline-item"><time>${e(x.at.slice(0,16).replace('T',' '))}</time><h3>${e(x.title)}</h3><p>${e(x.detail)}</p><small>${e(x.by)} · ${e(x.source)}</small></article>`).join('')||'<div class="empty">Chưa có hoạt động CSKH được ghi nhận.</div>'}</div></section>`;}
  function patient(p) {const c=C.profile(p),tasks=C.queue({patient:p.id,allDates:true});return summary(p)+`<div class="crm-dashboard-grid"><section class="panel"><div class="panel-title">Bối cảnh chăm sóc<small>Dữ liệu từ hồ sơ và liệu trình</small></div><dl class="crm-facts"><div><dt>Nguồn khách</dt><dd>${e(c.source)}</dd></div><div><dt>Tiếp xúc đầu tiên</dt><dd>${day(c.firstContactAt)}</dd></div><div><dt>Khám gần nhất</dt><dd>${day(c.lastVisitAt)}</dd></div><div><dt>Liệu trình</dt><dd>${e(p.plan)} · còn ${c.remaining} buổi</dd></div><div><dt>Kết quả CSKH gần nhất</dt><dd>${e(C.outcomes[c.latestOutcome]||'Chưa liên hệ')}</dd></div><div><dt>Bước tiếp</dt><dd>${day(c.nextActionAt)} · ${e(c.nextActionType||'Theo hàng đợi')}</dd></div></dl><div class="actions">${btn('Sửa ngày dự kiến','expected',p.id)}<button class="btn" data-tab="plan">Xem liệu trình</button><button class="btn" data-tab="history">Toàn bộ lịch sử →</button></div></section><section class="panel"><div class="panel-title">Việc còn mở<small>${tasks.length} việc gắn với hồ sơ</small></div>${tasks.map(t=>`<div class="crm-task-row"><div><strong>${e(t.reason)}</strong><small>${day(t.dueAt)} · ${e(t.owner)}</small></div>${btn('Xử lý','task',t.id,true)}</div>`).join('')||'<p class="empty">Không còn việc CSKH mở.</p>'}</section></div>${timeline(p,true)}`;}
  function financial(p){return `<section class="panel"><div class="panel-head"><div class="panel-title">Hóa đơn của ${e(p.name)}<small>Giá trị phát sinh, tiền đã thu và dư nợ; không suy hoàn tất điều trị</small></div>${window.PemaStaff?.can('billing')?'<button class="btn" data-nav="cashier">Mở thu ngân →</button>':''}</div><div class="crm-table-scroll"><table class="table crm-table"><thead><tr><th>Hóa đơn</th><th>Dịch vụ</th><th>Phát sinh</th><th>Đã thu</th><th>Còn lại</th></tr></thead><tbody>${p.invoices.map(i=>{const received=i.paid?i.amount:i.received||0;return `<tr><td>${e(i.id)}<small>${day(i.date)}</small></td><td>${e(i.label)}</td><td>${P.money(i.amount)}</td><td>${P.money(received)}</td><td>${P.money(i.amount-received)}</td></tr>`;}).join('')}</tbody></table></div><p class="notice">Tiền cọc còn chưa phân bổ: ${P.money((p.depositLedger||[]).reduce((sum,x)=>sum+Math.max(0,x.received-x.applied),0))}. Cọc đã phân bổ được thể hiện riêng trong liệu trình bên dưới.</p></section>`;}
  function clinical(p){return `<section class="panel crm-clinical"><div class="panel-head"><div class="panel-title">Tiền sử & chẩn đoán<small>Bác sĩ ghi nhận, không dùng AI tự chẩn đoán</small></div></div><form id="crm-clinical-form" data-patient-id="${p.id}"><div class="two-col-form">${field('Tiền sử đã khai thác','crm-history',`<textarea id="crm-history" required>${e(p.clinical?.history||'')}</textarea>`)}${field('Khám / chẩn đoán do bác sĩ xác nhận','crm-diagnosis',`<textarea id="crm-diagnosis" required>${e(p.clinical?.diagnosis||'')}</textarea>`)}</div><button class="btn" type="submit">Bác sĩ lưu nhận định</button><p class="crm-error" role="alert"></p></form></section>`;}
  function modal(title,body){host.modal(`<div class="modal-backdrop"><section class="modal crm-modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-head"><h2>${title}</h2><button class="modal-close" aria-label="Đóng hộp thoại">×</button></div>${body}<p id="crm-error" class="crm-error" role="alert"></p></section></div>`);}
  function task(id) {
    const t=P.state.crmTasks.find(t=>t.id===id),p=P.patient(t.patientId),c=C.profile(p);
    modal('Chăm sóc · '+e(p.name),`<div class="crm-context"><div>${badge(t.reason,true)}<p>${e(p.plan)} · Còn <b>${c.remaining} buổi</b></p><small>Khám: ${day(p.lastVisit)} · Dự kiến: ${day(c.expectedNextVisitAt)} · Quá hạn ${c.overdueDays} ngày</small><small>Liên hệ gần nhất: ${day(c.lastContactAt)} · ${e(C.outcomes[c.latestOutcome]||'Chưa ghi nhận')}</small></div>${btn('Patient 360 →','patient-crm',p.id)}</div><p class="notice">Ghi nhận cuộc gọi/tin nhắn mô phỏng. Không gửi Zalo/SMS hoặc thực hiện cuộc gọi thật.</p><form id="crm-task-form" data-task="${e(id)}"><div class="two-col-form">${field('Kênh liên hệ','crm-channel',select('crm-channel',['Gọi điện','Zalo','SMS','Ghi chú nội bộ'].map(x=>[x,x]),'Gọi điện'))}${field('Kết quả','crm-outcome',select('crm-outcome',Object.entries(C.outcomes),'callback'))}</div>${field('Nội dung / kết quả trao đổi','crm-note','<textarea id="crm-note" required placeholder="Ghi cụ thể kết quả và điều đã thống nhất với khách…"></textarea>')}<div class="two-col-form">${field('Ngày giờ tiếp theo (nếu cần)','crm-next','<input id="crm-next" type="datetime-local" min="2026-09-20T09:01">')}${field('Hành động tiếp theo','crm-next-type',select('crm-next-type',[['call','Gọi lại'],['review','Bác sĩ xem'],['book','Đặt lịch'],['message','Nhắn chăm sóc']],'call'))}${field('Phụ trách','crm-owner',select('crm-owner',owners.map(x=>[x,x]),t.owner))}${field('Ưu tiên','crm-priority',select('crm-priority',Object.entries(labelPriority),t.priority))}</div><div class="crm-form-footer"><button class="btn btn-primary" type="submit" id="crm-submit">Lưu kết quả chăm sóc</button><small>Đồng ý đặt lịch sẽ mở form lịch trước khi hoàn tất.</small></div></form>`);
  }
  function readInput(){const v=id=>document.getElementById(id).value;return {channel:v('crm-channel'),outcome:v('crm-outcome'),note:v('crm-note'),nextActionAt:v('crm-next'),nextActionType:v('crm-next-type'),owner:v('crm-owner'),priority:v('crm-priority')};}
  function handle(action,id) {
    if(action==='doctor-today')return host.navigate('today');if(action==='doctor-patients')return host.navigate('patients');if(action==='doctor-followups')return host.navigate('followups');
    if(action==='queue'){rule=id||'all';queuePage=1;host.navigate('crm');}
    if(action==='filter'){rule=id;queuePage=1;host.render();}
    if(action==='queue-page'){queuePage=Math.max(1,queuePage+Number(id));host.render();}
    if(action==='today-page'){todayPage=Math.max(1,todayPage+Number(id));host.render();}
    if(action==='today-status'){todayStatus=id;todayPage=1;host.render();}
    if(action==='profile')host.patient(id);
    if(action==='patient-crm')host.patient(id,'crm');
    if(action==='task')task(id);
    if(['arrive','start','missed'].includes(action)){C.reception(id,{arrive:'arrived',start:'in_progress',missed:'missed'}[action]);host.render();host.toast('Đã cập nhật hàng đợi');}
    if(action==='expected'){const p=P.patient(id);modal('Ngày dự kiến quay lại',`<form id="crm-expected-form" data-patient-id="${p.id}">${field('Ngày bác sĩ/CSKH khuyến nghị','crm-expected-date',`<input type="date" id="crm-expected-date" value="${e(p.crm.recommendationAt||'')}" required>`)}${field('Lý do','crm-expected-reason',`<input id="crm-expected-reason" value="${e(p.crm.expectedVisitReason||'')}" required>`)}${field('Nguồn','crm-expected-source',select('crm-expected-source',Object.entries(C.sources).filter(([k])=>k!=='appointment'),p.crm.expectedVisitSource))}<p class="notice">Nếu đã có lịch thực tế, Patient 360 ưu tiên ngày lịch đó. Khuyến nghị vẫn được giữ khi hủy lịch.</p><button class="btn btn-primary" type="submit">Lưu ngày dự kiến</button></form>`);}
    if(action==='protocol')modal('Protocol chăm sóc mẫu',`<p class="subtitle">Hoàn tất Laser CO2 → D+1 hỏi tình trạng → D+3 yêu cầu ảnh → D+7 bác sĩ review → D+30 dự kiến tái khám.</p><div class="crm-protocol">${P.state.crmAutomationRules.map(r=>`<article><strong>${e(r.name)}</strong><p>${e(r.suggestedAction)}</p><small>${e({session_completed:'Hoàn tất buổi',expected_visit:'Ngày dự kiến',appointment_missed:'Hủy/vắng hẹn',remaining_sessions:'Còn buổi',last_visit:'Lần khám gần nhất',birthday:'Ngày sinh'}[r.trigger]||r.name)} → ${r.delayDays} ngày → tạo việc cho ${r.id==='d7'?'bác sĩ':'CSKH'}</small></article>`).join('')}</div><div class="notice">Ngưỡng và nội dung là mẫu cần chủ phòng khám duyệt trước pilot. Không tự gửi tin hoặc tự duyệt y khoa.</div>`);
    if(action==='activity')modal('Kết quả chăm sóc đã ghi',`<div class="crm-activity-list">${P.state.crmActivities.map(a=>`<article><strong>${e(P.patient(a.patientId).name)} · ${e(C.outcomes[a.outcome])}</strong><p>${e(a.note)}</p><small>${e(a.actor)} · ${e(a.occurredAt)}${a.relatedAppointmentId?' · '+e(a.relatedAppointmentId):''}</small></article>`).join('')||'<p class="empty">Chưa có kết quả. Bắt đầu từ CSKH hôm nay.</p>'}</div>`);
    if(action==='segment')modal(C.stageLabels[id],P.state.patients.filter(p=>C.profile(p).lifecycleStage===id).map(p=>`<div class="crm-task-row"><strong>${e(p.name)}</strong>${btn('Mở hồ sơ','patient-crm',p.id)}</div>`).join('')||'<p>Chưa có khách trong nhóm.</p>');
  }
  function bind(h) {
    host=h;
    document.querySelectorAll('[data-crm]').forEach(b=>b.onclick=()=>{try{handle(b.dataset.crm,b.dataset.id);}catch(err){host.toast(err.message);}});
    for(const [id,assign] of [['crm-search',v=>query=v],['crm-owner-filter',v=>owner=v],['crm-mode',v=>queueMode=v],['crm-today-search',v=>todayQuery=v],['crm-today-status',v=>todayStatus=v],['crm-today-doctor',v=>todayDoctor=v]]) {
      const x=document.getElementById(id);if(x)x.onchange=()=>{assign(x.value);queuePage=todayPage=1;host.render();};
    }
    const form=document.getElementById('crm-task-form');
    if(form){document.getElementById('crm-outcome').onchange=ev=>{document.getElementById('crm-submit').textContent=ev.target.value==='booked'?'Tiếp tục → Đặt lịch':'Lưu kết quả chăm sóc';};form.onsubmit=ev=>{ev.preventDefault();try{const input=readInput(),t=P.state.crmTasks.find(t=>t.id===form.dataset.task);if(input.outcome==='booked'){input.nextActionAt=null;C.bookingGuard(t.id,input,t.patientId);PemaOpsUI.openBooking({patient:t.patientId,date:'2026-09-27',note:'Sau CSKH: '+input.note},{crmTaskId:t.id,crmInput:input});return;}C.resolve(t.id,input);host.close();host.toast('Đã lưu kết quả và cập nhật hàng đợi');}catch(err){document.getElementById('crm-error').textContent=err.message;}};}
    const f=document.getElementById('crm-expected-form');if(f)f.onsubmit=ev=>{ev.preventDefault();try{C.expected(f.dataset.patientId,{date:document.getElementById('crm-expected-date').value,reason:document.getElementById('crm-expected-reason').value,source:document.getElementById('crm-expected-source').value});host.close();host.toast('Đã cập nhật ngày dự kiến');}catch(err){document.getElementById('crm-error').textContent=err.message;}};
    const cf=document.getElementById('crm-clinical-form');if(cf)cf.onsubmit=ev=>{ev.preventDefault();try{C.clinical(cf.dataset.patientId,{history:document.getElementById('crm-history').value,diagnosis:document.getElementById('crm-diagnosis').value});host.render();host.toast('Đã lưu nhận định có bác sĩ xác nhận');}catch(err){cf.querySelector('.crm-error').textContent=err.message;}};
  }
  window.addEventListener('pema-staff-change',()=>{rule='all';owner=window.PemaStaff.current().owner||'all';query='';queuePage=1;todayStatus='all';todayDoctor='all';todayQuery='';});
  window.PemaCRMUI={financial,doctorHome,bind,queue,dashboard,today,patient,summary,timeline,clinical};
})();
